// Who is in the café and what each one is doing: the roster one session keeps
// of its own agents, moved along by the session's events.
//
// The hooks module owns one roster and calls these functions from its hooks;
// every function takes the time as an argument and touches nothing else, so
// the same calls in a test give the same roster.

import type { Act } from './describe'

/**
 * Where a seat stands: between tool calls, in one, held for the person,
 * resting with no turn running, or gone (done, failed).
 */
export type Phase = 'think' | 'work' | 'ask' | 'idle' | 'done' | 'fail'

/** The main loop, a subagent, or a teammate (which rests between its turns). */
export type Kind = 'main' | 'sub' | 'mate'

/** The main loop's id in the roster: its events carry no `agentId`. */
export const MAIN = 'main'

/** How long a subagent that finished keeps its seat before it leaves. */
export const LINGER_MS = 20_000
/** How long a loop nothing has named is remembered before it is forgotten. */
export const GHOST_MS = 60_000
/** How long a quiet agent the list never named is kept. */
export const STALE_MS = 30 * 60_000
/** How long a call in flight keeps an agent nothing else has been heard of. */
export const CALL_STALE_MS = 12 * 60 * 60_000
/** How long the list must go on leaving an agent out before the café believes it. */
export const MISS_MS = 4_000
/** The list may be a moment behind the events: an end this recent stands against it. */
const SETTLE_MS = 10_000

/** One tool call in flight. */
type Call = {
  id: string
  tool: string
  act: Act
  target: string
  at: number
  /** Held at a permission prompt since `askAt`. */
  isAsking: boolean
  askAt: number
  /** The tool the prompt that holds it named; `''` when it named none. */
  askedFor: string
}

/** One agent of this session, as the roster keeps it. */
export type Agent = {
  id: string
  kind: Kind
  /** `main`, the subagent type, or `''` until something says. */
  type: string
  /** What SendMessage addresses it by, when it has a name. */
  name: string
  /** The few words its spawn described the task in. */
  task: string
  /** The agent whose loop spawned it; `''` when the main loop did. */
  parent: string
  phase: Phase
  act: Act
  tool: string
  target: string
  /** When what it shows now began. */
  since: number
  born: number
  /** When it finished; 0 while it is here. */
  ended: number
  /** Tool calls so far. */
  calls: number
  open: Call[]
  /** The person is asked for, with no open call to pin it on. */
  needsPerson: boolean
  /**
   * True while a turn of its own runs: with nothing in flight it is thinking.
   * False between turns, where with nothing in flight it rests.
   */
  inTurn: boolean
  /** True when the main loop's last turn ended on an error: it rests as failed. */
  hasFailed: boolean
  /** False while only loop events have named it: such a seat is not shown. */
  isKnown: boolean
  /** True once `$.agent.list()` named it: its absence there then means it left. */
  isListed: boolean
  /** When the list first left it out, having named it before; 0 while it is listed. */
  missedAt: number
  /** When an event last named it. */
  seen: number
}

export type Roster = { agents: Agent[] }

/** What a seat shows, the part of an agent the café draws and shares. */
export type Seat = {
  id: string
  kind: Kind
  type: string
  name: string
  task: string
  parent: string
  phase: Phase
  act: Act
  tool: string
  target: string
  since: number
  calls: number
}

/** One agent as `$.agent.list()` answers it: the fields the roster reads. */
export type Listed = {
  id: string
  type: string
  description: string
  status: string
  parentId?: string
  name?: string
  teammateId?: string
}

/** What a spawn says of the agent it started. */
export type Spawned = {
  id: string
  type: string
  task: string
  parent: string
  name: string
  isTeammate: boolean
}

/** Why a turn ended, as `turn.complete` says it. */
export type EndReason = 'answer' | 'aborted' | 'refusal' | 'error'

function blank(id: string, kind: Kind, now: number): Agent {
  return {
    id,
    kind,
    type: kind === 'main' ? MAIN : '',
    name: '',
    task: '',
    parent: '',
    phase: kind === 'main' ? 'idle' : 'think',
    act: kind === 'main' ? 'rest' : 'think',
    tool: '',
    target: '',
    since: now,
    born: now,
    ended: 0,
    calls: 0,
    open: [],
    needsPerson: false,
    // The main loop is met between turns; anyone else is met at work.
    inTurn: kind !== 'main',
    hasFailed: false,
    isKnown: kind === 'main',
    isListed: false,
    missedAt: 0,
    seen: now,
  }
}

/** A roster with the main loop at its seat, resting. */
export function createRoster(now: number): Roster {
  return { agents: [blank(MAIN, 'main', now)] }
}

function find(roster: Roster, id: string): Agent | undefined {
  return roster.agents.find(agent => agent.id === id)
}

/** The agent an event names, seated unseen when nothing has named it before. */
function ensure(roster: Roster, agentId: string | undefined, now: number): Agent {
  const id = agentId ?? MAIN
  let agent = find(roster, id)
  if (agent === undefined) {
    agent = blank(id, id === MAIN ? 'main' : 'sub', now)
    roster.agents.push(agent)
  }
  agent.seen = now
  return agent
}

function put(agent: Agent, phase: Phase, act: Act, tool: string, target: string, since: number): void {
  if (agent.phase === phase && agent.act === act && agent.tool === tool && agent.target === target) return
  agent.phase = phase
  agent.act = act
  agent.tool = tool
  agent.target = target
  agent.since = since
}

function lastWhere<T>(items: readonly T[], test: (item: T) => boolean): T | undefined {
  for (let index = items.length - 1; index >= 0; index -= 1) {
    const item = items[index]
    if (item !== undefined && test(item)) return item
  }
  return undefined
}

/** Works out what a live agent shows from its calls in flight and whether a turn runs. */
function show(agent: Agent, now: number): void {
  if (agent.ended !== 0) return
  // A call held for the person outranks the rest: that is the one to see.
  const held = lastWhere(agent.open, call => call.isAsking || call.act === 'ask')
  const top = held ?? agent.open[agent.open.length - 1]
  if (top !== undefined) {
    const isHeld = top.isAsking || top.act === 'ask'
    put(agent, isHeld ? 'ask' : 'work', top.act, top.tool, top.target, top.isAsking ? top.askAt : top.at)
    return
  }
  if (agent.needsPerson) {
    put(agent, 'ask', 'ask', '', '', now)
    return
  }
  if (agent.inTurn) {
    put(agent, 'think', 'think', '', '', now)
    return
  }
  // Between turns there is nothing to think about: a call that ran there (a
  // plugin's own, say) leaves the agent as its last turn did.
  if (agent.hasFailed) put(agent, 'fail', 'fail', '', '', now)
  else put(agent, 'idle', 'rest', '', '', now)
}

/**
 * An agent is over: done, failed, or cut short (stopped by the person or
 * killed), which has nothing to show for it and so leaves at the next sweep.
 */
function leave(agent: Agent, how: 'done' | 'fail' | 'cut', now: number): void {
  agent.open = []
  agent.needsPerson = false
  agent.inTurn = false
  const phase = how === 'fail' ? 'fail' : 'done'
  put(agent, phase, phase, '', '', now)
  agent.ended = how === 'cut' ? now - LINGER_MS : now
}

function rest(agent: Agent, now: number): void {
  agent.open = []
  agent.needsPerson = false
  agent.inTurn = false
  agent.hasFailed = false
  put(agent, 'idle', 'rest', '', '', now)
}

/** A main-loop turn began: the main loop is thinking, whatever it showed. */
export function turnStart(roster: Roster, now: number): void {
  const agent = ensure(roster, undefined, now)
  agent.open = []
  agent.needsPerson = false
  agent.ended = 0
  agent.inTurn = true
  agent.hasFailed = false
  put(agent, 'think', 'think', '', '', now)
}

/** A tool call began in an agent's loop. */
export function toolStart(
  roster: Roster,
  agentId: string | undefined,
  call: { id: string; tool: string; act: Act; target: string },
  now: number,
): void {
  const agent = ensure(roster, agentId, now)
  // An agent that finished, or rested, and works again was resumed under its
  // id. Not so the main loop: a call may run there with no turn (a plugin's).
  agent.ended = 0
  if (agent.kind !== 'main') agent.inTurn = true
  agent.needsPerson = false
  agent.calls += 1
  agent.open = agent.open.filter(open => open.id !== call.id)
  agent.open.push({ ...call, at: now, isAsking: false, askAt: 0, askedFor: '' })
  show(agent, now)
}

/** A tool call ended, however it ended. */
export function toolEnd(roster: Roster, agentId: string | undefined, id: string, now: number): void {
  const agent = find(roster, agentId ?? MAIN)
  if (agent === undefined) return
  agent.seen = now
  const before = agent.open.length
  agent.open = agent.open.filter(open => open.id !== id)
  // A call the roster no longer holds ended a turn ago: nothing to show for it.
  if (agent.open.length === before) return
  // A call got through, so the agent is moving again: nothing unpinned holds it.
  agent.needsPerson = false
  show(agent, now)
}

/**
 * An agent is held for the person: `tool` names the call a prompt holds and
 * `target` what that call works on, each `''` when the prompt does not say.
 *
 * The hold is pinned on the newest open call of that name and target, else of
 * that name, else on the newest open call, and ends with that call. With no
 * call open it stands on the agent itself until its next call, the end of its
 * turn, or `askOver`.
 *
 * @returns the id of the call the hold was pinned on, if it was pinned on one
 */
export function ask(
  roster: Roster,
  agentId: string | undefined,
  tool: string,
  target: string,
  now: number,
): string | undefined {
  const agent = ensure(roster, agentId, now)
  if (agent.ended !== 0) return undefined
  const call =
    lastWhere(agent.open, open => !open.isAsking && open.tool === tool && open.target === target) ??
    lastWhere(agent.open, open => !open.isAsking && open.tool === tool) ??
    lastWhere(agent.open, open => !open.isAsking)
  if (call !== undefined) {
    call.isAsking = true
    call.askAt = now
    call.askedFor = tool
  } else if (!agent.open.some(open => open.isAsking)) {
    agent.needsPerson = true
  }
  show(agent, now)
  return call?.id
}

/** The hold is over without the call having run: one call's by id, or all. */
export function askOver(roster: Roster, agentId: string | undefined, id: string | undefined, now: number): void {
  const agent = find(roster, agentId ?? MAIN)
  if (agent === undefined) return
  agent.seen = now
  agent.needsPerson = false
  for (const call of agent.open) {
    if (id === undefined || call.id === id) call.isAsking = false
  }
  show(agent, now)
}

/**
 * A call got through without having ended, as an Agent call does when its
 * agent starts: the hold a prompt about that very call pinned on it is over.
 *
 * A hold pinned there for want of a better call, and one on the agent itself,
 * stand: the agent starting says nothing about those.
 */
export function callThrough(roster: Roster, agentId: string | undefined, id: string, now: number): void {
  const agent = find(roster, agentId ?? MAIN)
  if (agent === undefined) return
  const call = agent.open.find(open => open.id === id)
  if (call === undefined || !call.isAsking || call.askedFor !== call.tool) return
  call.isAsking = false
  show(agent, now)
}

/** A subagent or a teammate started: seat it, or name the one a loop event seated. */
export function spawn(roster: Roster, info: Spawned, now: number): void {
  let agent = find(roster, info.id)
  if (agent === undefined) {
    agent = blank(info.id, info.isTeammate ? 'mate' : 'sub', now)
    roster.agents.push(agent)
  }
  agent.kind = info.isTeammate ? 'mate' : 'sub'
  agent.isKnown = true
  agent.seen = now
  if (info.type !== '') agent.type = info.type
  if (info.task !== '') agent.task = info.task
  if (info.name !== '') agent.name = info.name
  agent.parent = info.parent
  // One that has already finished stays finished: a spawn names an agent, it
  // does not wake one. A later tool call, or the list, says it runs again.
}

/**
 * The SubagentStart event: the agent is real, and this is its type.
 *
 * One that starts with no type is a loop of the engine's own (a summary, a
 * suggestion): it takes no seat unless a spawn or the list names it.
 */
export function subStart(roster: Roster, id: string, type: string, now: number): void {
  const agent = ensure(roster, id, now)
  if (type === '') return
  agent.isKnown = true
  if (agent.type === '') agent.type = type
}

/**
 * A turn ended: the main loop and a teammate rest, a subagent is done, or
 * failed, or (interrupted) simply gone.
 */
export function turnEnd(roster: Roster, agentId: string | undefined, reason: EndReason, now: number): void {
  const agent = find(roster, agentId ?? MAIN)
  if (agent === undefined) return
  agent.seen = now
  const hasFailed = reason === 'error' || reason === 'refusal'
  if (agent.kind === 'main') {
    agent.open = []
    agent.needsPerson = false
    agent.inTurn = false
    agent.hasFailed = hasFailed
    show(agent, now)
    return
  }
  if (agent.kind === 'mate') {
    rest(agent, now)
    return
  }
  if (agent.ended === 0) leave(agent, hasFailed ? 'fail' : reason === 'aborted' ? 'cut' : 'done', now)
}

/** The SubagentStop event: a subagent is done, a teammate rests. */
export function subStop(roster: Roster, id: string, now: number): void {
  const agent = find(roster, id)
  if (agent === undefined || agent.ended !== 0) return
  agent.seen = now
  if (agent.kind === 'mate') rest(agent, now)
  else if (agent.kind === 'sub') leave(agent, 'done', now)
}

/** The TeammateIdle event names the teammate, not its id. */
export function mateIdle(roster: Roster, name: string, now: number): void {
  const agent = roster.agents.find(mate => mate.kind === 'mate' && mate.name === name && mate.ended === 0)
  if (agent === undefined) return
  agent.seen = now
  rest(agent, now)
}

/**
 * What the list's word for an agent means to the café: at work, over, or
 * parked between turns.
 *
 * `idle` and `waiting` are the parked ones. A teammate parks between its turns
 * and is still here. Any other agent is listed under those words once its turn
 * has ended, for as long as it can still be sent a message or a shell of its
 * own still runs, and also while it waits on an agent of its own: by
 * themselves they are no sign of life, and a call in flight is.
 */
function standingOf(status: string): 'live' | 'parked' | 'over' {
  if (status === 'completed' || status === 'failed' || status === 'killed') return 'over'
  if (status === 'running' || status === 'pending') return 'live'
  return 'parked'
}

/**
 * Reconciles the roster with `$.agent.list()`: seats whoever the events missed,
 * fills in what an event did not say, and lets go of whoever the list dropped.
 *
 * The events stay the authority on what a running agent is doing; the list
 * says who exists and who is over.
 */
export function sync(roster: Roster, list: readonly Listed[], now: number): void {
  const ids = new Set<string>()
  for (const info of list) {
    ids.add(info.id)
    const standing = standingOf(info.status)
    let agent = find(roster, info.id)
    const isMate = info.teammateId !== undefined || agent?.kind === 'mate'
    if (agent === undefined || !agent.isKnown) {
      // Whoever was over, or parked with its turn behind it, before the café
      // looked never sits down: neither one nothing has named, nor one only
      // its loop's last events have (an agent that was finishing as the mod
      // loaded). A teammate that rests is still one of the team.
      // One with a call in flight is at work whatever the list calls it: a
      // subagent waiting on an agent of its own is listed `waiting`.
      const isMidCall = agent !== undefined && agent.ended === 0 && agent.open.length > 0
      if (standing === 'over' || (standing === 'parked' && !isMate && !isMidCall)) continue
      // Nor one the events saw end a moment ago, which the list has yet to hear.
      if (agent !== undefined && agent.ended !== 0 && now - agent.ended <= SETTLE_MS) continue
    }
    if (agent === undefined) {
      agent = blank(info.id, isMate ? 'mate' : 'sub', now)
      roster.agents.push(agent)
    }
    agent.isKnown = true
    agent.isListed = true
    agent.missedAt = 0
    if (info.teammateId !== undefined) agent.kind = 'mate'
    if (agent.type === '' && info.type !== '') agent.type = info.type
    if (agent.task === '' && info.description !== '') agent.task = info.description
    if (agent.name === '' && info.name !== undefined) agent.name = info.name
    if (agent.parent === '' && info.parentId !== undefined) agent.parent = info.parentId

    if (standing === 'over') {
      if (agent.ended === 0) leave(agent, info.status === 'failed' ? 'fail' : info.status === 'killed' ? 'cut' : 'done', now)
    } else if (standing === 'parked') {
      // Its turn is behind it. One the events still had at work, with nothing
      // in flight, rests; one that finished stays finished.
      if (agent.ended === 0 && agent.open.length === 0 && agent.kind !== 'main') rest(agent, now)
    } else if (agent.ended !== 0) {
      // Running again under its id, unless the list is only a moment behind.
      if (now - agent.ended > SETTLE_MS) {
        agent.ended = 0
        agent.inTurn = true
        show(agent, now)
      }
    } else if (!agent.inTurn && agent.kind !== 'main') {
      // It rested, and runs again.
      agent.inTurn = true
      show(agent, now)
    }
  }

  // Whoever the list named and has since dropped is gone, once a later look agrees.
  for (const agent of roster.agents) {
    if (agent.kind === 'main' || !agent.isListed || agent.ended !== 0 || ids.has(agent.id)) continue
    if (agent.missedAt === 0) agent.missedAt = now
    else if (now - agent.missedAt >= MISS_MS) leave(agent, 'done', now)
  }
}

/**
 * Lets go of whoever has stayed long enough: the finished after a while, the
 * unnamed and the long quiet after longer. True when someone left.
 */
export function sweep(roster: Roster, now: number): boolean {
  const before = roster.agents.length
  roster.agents = roster.agents.filter(agent => {
    if (agent.kind === 'main') return true
    if (agent.ended !== 0) return now - agent.ended < LINGER_MS
    if (!agent.isKnown) return now - agent.seen < GHOST_MS
    if (agent.isListed) return true
    // A call in flight keeps its agent, unless neither has been heard of for
    // half a day: then the call's end was lost.
    if (agent.open.length > 0) return now - agent.seen < CALL_STALE_MS
    return now - agent.seen < STALE_MS
  })
  return roster.agents.length !== before
}

/**
 * The conversation was cleared: the main loop starts over, at rest.
 *
 * Its agents keep their seats. A clear does not end them: one still running
 * goes on and reports to the new conversation, and one the clear stops says
 * so itself, as any agent that stops does.
 */
export function reset(roster: Roster, now: number): void {
  let main = find(roster, MAIN)
  if (main === undefined) {
    main = blank(MAIN, 'main', now)
    roster.agents.unshift(main)
  }
  rest(main, now)
  // Rested already, it still starts over: its time at rest counts from now.
  main.since = now
  main.calls = 0
}

function toSeat(agent: Agent): Seat {
  return {
    id: agent.id,
    kind: agent.kind,
    type: agent.type,
    name: agent.name,
    task: agent.task,
    parent: agent.parent,
    phase: agent.phase,
    act: agent.act,
    tool: agent.tool,
    target: agent.target,
    since: agent.since,
    calls: agent.calls,
  }
}

/**
 * The seats to draw, in table order: the main loop, then each agent it
 * spawned in the order they came, each followed by the agents it spawned.
 */
export function seatsOf(roster: Roster): Seat[] {
  const shown = roster.agents.filter(agent => agent.isKnown)
  const ids = new Set(shown.map(agent => agent.id))
  const childrenOf = (parent: string): Agent[] =>
    shown
      .filter(agent => agent.kind !== 'main' && (agent.parent === parent || (parent === '' && !ids.has(agent.parent))))
      .sort((one, other) => one.born - other.born)

  const out: Seat[] = []
  const placed = new Set<string>()
  const place = (agent: Agent): void => {
    if (placed.has(agent.id)) return
    placed.add(agent.id)
    out.push(toSeat(agent))
    for (const child of childrenOf(agent.id)) place(child)
  }
  for (const agent of shown) {
    if (agent.kind === 'main') {
      placed.add(agent.id)
      out.push(toSeat(agent))
    }
  }
  for (const agent of childrenOf('')) place(agent)
  // A cycle of parents would leave agents unplaced: seat them all the same.
  for (const agent of shown) place(agent)
  return out
}

/** How deep a seat sits under the main loop: 1 for its own subagents, 2 for theirs. */
export function depthOf(seats: readonly Seat[], seat: Seat): number {
  if (seat.kind === 'main') return 0
  let depth = 1
  let parent = seat.parent
  const walked = new Set<string>([seat.id])
  while (parent !== '' && !walked.has(parent)) {
    const above = seats.find(other => other.id === parent)
    if (above === undefined || above.kind === 'main') break
    walked.add(parent)
    depth += 1
    parent = above.parent
  }
  return depth
}

files.hooks/view.ts:
// From rosters to what the café shows: the tables (one per session), who sits
// where and under what name, and the same thing as lines of text.
//
// Pure: no `$` here.

import type { Act } from './describe'
import { clip, tidy } from './describe'
import type { Words } from './i18n'
import { age, say } from './i18n'
import type { Kind, Phase, Seat } from './tracker'
import { depthOf } from './tracker'

/**
 * What one session shares with the others through the store: who it is, when
 * it last said so, and its seats.
 */
export type Snap = {
  v: 1
  id: string
  /** The session's folder name, which names its table. */
  title: string
  /** When it was written, in milliseconds: an old one is a session that is gone. */
  at: number
  seats: Seat[]
}

/** One seat as drawn: the roster's seat, its name at the table and what it says. */
export type Place = {
  /** Unique in the café: the table's id and the seat's. */
  key: string
  seat: Seat
  label: string
  says: string
  /** 0 for the main loop, 1 for its subagents, 2 for theirs. */
  depth: number
  /** True for the agent whose transcript the person has on screen. */
  isViewed: boolean
}

export type Table = {
  id: string
  title: string
  /** True for the session the pane is open in. */
  isHere: boolean
  places: Place[]
  /** Seats the table has and does not show. */
  hidden: number
}

export type Cafe = {
  tables: Table[]
  /** Seats thinking or in a tool call, over every table, shown or not. */
  busy: number
  /** Seats held for the person. */
  asking: number
  /** Seats resting, done or failed. */
  idle: number
  /** Seats shown. */
  seats: number
  /** Tables past the ones shown. */
  hiddenTables: number
}

/** The most seats one table shows, and the most tables. */
export const TABLE_SEATS = 12
export const MAX_TABLES = 4

const PHASES: readonly Phase[] = ['think', 'work', 'ask', 'idle', 'done', 'fail']
const KINDS: readonly Kind[] = ['main', 'sub', 'mate']
const ACTS: readonly Act[] = [
  'read',
  'search',
  'write',
  'run',
  'web',
  'delegate',
  'plan',
  'ask',
  'tool',
  'think',
  'rest',
  'done',
  'fail',
]

function isRecord(value: unknown): value is Readonly<Record<string, unknown>> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function word(value: unknown, max: number): string {
  return typeof value === 'string' ? clip(tidy(value), max) : ''
}

function oneOf<T extends string>(value: unknown, among: readonly T[], fallback: T): T {
  return among.find(item => item === value) ?? fallback
}

function count(value: unknown): number {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0 ? Math.floor(value) : 0
}

function parseSeat(value: unknown): Seat | undefined {
  if (!isRecord(value)) return undefined
  const id = word(value['id'], 80)
  if (id === '') return undefined
  return {
    id,
    kind: oneOf(value['kind'], KINDS, 'sub'),
    type: word(value['type'], 40),
    name: word(value['name'], 40),
    task: word(value['task'], 80),
    parent: word(value['parent'], 80),
    phase: oneOf(value['phase'], PHASES, 'think'),
    act: oneOf(value['act'], ACTS, 'think'),
    tool: word(value['tool'], 80),
    target: word(value['target'], 60),
    since: count(value['since']),
    calls: count(value['calls']),
  }
}

/**
 * Reads what another session left in the store. The store is shared by every
 * session of the machine, so nothing in it is taken on trust: a value of
 * another shape is no snap, and every string is cut to a length.
 */
export function parseSnap(value: unknown): Snap | undefined {
  if (!isRecord(value) || value['v'] !== 1) return undefined
  const id = word(value['id'], 80)
  const seats = value['seats']
  if (id === '' || !Array.isArray(seats)) return undefined
  const parsed: Seat[] = []
  for (const item of seats.slice(0, 64)) {
    const seat = parseSeat(item)
    if (seat !== undefined) parsed.push(seat)
  }
  return { v: 1, id, title: word(value['title'], 40), at: count(value['at']), seats: parsed }
}

function baseLabel(seat: Seat, words: Words): string {
  if (seat.kind === 'main') return words.main
  return seat.name || seat.type || words.agent
}

function isOver(phase: Phase): boolean {
  return phase === 'done' || phase === 'fail'
}

/** At work: thinking, in a tool call, or held in one for the person. */
function isLive(phase: Phase): boolean {
  return phase === 'think' || phase === 'work' || phase === 'ask'
}

function seatTable(snap: Snap, isHere: boolean, words: Words, viewed: string | undefined, cap: number): Table {
  // When the table is full, the ones still here keep their seats.
  const ranked = snap.seats.map((seat, index) => ({ seat, index }))
  const kept =
    ranked.length <= cap
      ? ranked
      : [...ranked]
          .sort(
            (one, other) =>
              Number(other.seat.kind === 'main') - Number(one.seat.kind === 'main') ||
              Number(isOver(one.seat.phase)) - Number(isOver(other.seat.phase)) ||
              one.index - other.index,
          )
          .slice(0, cap)
          .sort((one, other) => one.index - other.index)

  // A main loop at rest waits for its own agents while any of them is at work.
  const hasCrew = snap.seats.some(seat => seat.kind !== 'main' && isLive(seat.phase))
  const seen = new Map<string, number>()
  const places = kept.map(({ seat }): Place => {
    const base = baseLabel(seat, words)
    const nth = (seen.get(base) ?? 0) + 1
    seen.set(base, nth)
    return {
      key: `${snap.id}/${seat.id}`,
      seat,
      label: nth === 1 ? base : `${base} ${nth}`,
      says: say(seat, words, hasCrew),
      depth: depthOf(snap.seats, seat),
      isViewed: isHere && viewed !== undefined && viewed === seat.id,
    }
  })
  return { id: snap.id, title: snap.title, isHere, places, hidden: snap.seats.length - kept.length }
}

/**
 * Seats everyone: this session's table first, then the others by name.
 *
 * @param viewed the agent whose transcript is on screen here, if one is
 * @param cap the most seats a table shows
 */
export function arrange(
  here: Snap,
  others: readonly Snap[],
  words: Words,
  viewed?: string,
  cap: number = TABLE_SEATS,
  maxTables: number = MAX_TABLES,
): Cafe {
  const rest = others
    .filter(snap => snap.id !== here.id && snap.seats.length > 0)
    .sort((one, other) => one.title.localeCompare(other.title) || one.id.localeCompare(other.id))
  const all = [here, ...rest]
  const shown = all.slice(0, Math.max(1, maxTables))
  const tables = shown.map(snap => seatTable(snap, snap === here, words, viewed, Math.max(1, cap)))
  return tallied(all, tables)
}

/**
 * Seats every table in the order given, none of them the viewer's own: the
 * café as the web page shows it, with every session a guest.
 *
 * @param cap the most seats a table shows
 * @param maxTables the most tables the picture holds
 */
export function arrangeAll(
  snaps: readonly Snap[],
  words: Words,
  cap: number = TABLE_SEATS,
  maxTables: number = MAX_TABLES,
): Cafe {
  const all = snaps.filter(snap => snap.seats.length > 0)
  const tables = all.slice(0, Math.max(1, maxTables)).map(snap => seatTable(snap, false, words, undefined, Math.max(1, cap)))
  return tallied(all, tables)
}

/** The café over `all` tables, `tables` of them shown: the tally counts every seat. */
function tallied(all: readonly Snap[], tables: Table[]): Cafe {
  let busy = 0
  let asking = 0
  let idle = 0
  for (const snap of all) {
    for (const seat of snap.seats) {
      if (seat.phase === 'ask') asking += 1
      else if (seat.phase === 'think' || seat.phase === 'work') busy += 1
      else idle += 1
    }
  }
  return {
    tables,
    busy,
    asking,
    idle,
    seats: tables.reduce((sum, table) => sum + table.places.length, 0),
    hiddenTables: all.length - tables.length,
  }
}

/** A table's name on its placard and in the list. */
export function tableTitle(table: Table, words: Words): string {
  const name = table.title === '' ? table.id.slice(0, 8) : table.title
  const here = table.isHere ? words.here(name) : name
  return table.hidden > 0 ? `${here} · ${words.more(table.hidden)}` : here
}

/** One line of the café as text: a table's name, or a seat. */
export type Line =
  | { type: 'table'; key: string; text: string }
  | {
      type: 'seat'
      key: string
      indent: string
      phase: Phase
      label: string
      /** The subagent's task, quoted as the language quotes; `''` for a seat with none. */
      note: string
      says: string
      /** How long it has been at it, and its tool calls. */
      tail: string
    }

/** The café as lines, in the order the picture seats it. */
export function linesOf(cafe: Cafe, words: Words, now: number): Line[] {
  const lines: Line[] = []
  const hasPlacards = cafe.tables.length > 1 || cafe.tables.some(table => table.hidden > 0)
  for (const table of cafe.tables) {
    if (hasPlacards) lines.push({ type: 'table', key: `t:${table.id}`, text: tableTitle(table, words) })
    for (const place of table.places) {
      const { seat } = place
      const parts = [age(now - seat.since)]
      if (seat.kind !== 'main' && seat.calls > 0) parts.push(words.calls(seat.calls))
      lines.push({
        type: 'seat',
        key: `s:${place.key}`,
        indent: place.depth === 0 ? '' : '  '.repeat(place.depth - 1) + '↳ ',
        phase: seat.phase,
        label: place.label,
        note: seat.task === '' ? '' : words.task(clip(seat.task, 44)),
        says: place.says,
        tail: parts.join(' · '),
      })
    }
  }
  return lines
}

/** The mark that stands for a phase; with a color where one can be drawn, alone where none can. */
export const MARKS: Readonly<Record<Phase, string>> = {
  think: '◐',
  work: '●',
  ask: '◆',
  idle: '○',
  done: '✓',
  fail: '✗',
}

/** The café as plain text, for a surface that draws no pane. */
export function textOf(cafe: Cafe, words: Words, now: number): string {
  const head = `${words.title} — ${words.tally(cafe.busy, cafe.asking, cafe.idle)}`
  const body = linesOf(cafe, words, now).map(line =>
    line.type === 'table'
      ? line.text
      : `${line.indent}${MARKS[line.phase]} ${line.label}${line.note} — ${line.says} · ${line.tail}`,
  )
  return [head, ...body].join('\n')
}

/**
 * Everything the picture depends on, as one string: two views with the same
 * signature draw the same picture, so the last one drawn can stand.
 */
export function signatureOf(cafe: Cafe): string {
  const tables = cafe.tables.map(table =>
    [
      table.id,
      table.title,
      table.isHere ? 1 : 0,
      table.hidden,
      ...table.places.map(place =>
        [place.key, place.label, place.seat.kind, place.seat.phase, place.seat.act, place.seat.tool, place.says, place.seat.task, place.isViewed ? 1 : 0].join('\u001f'),
      ),
    ].join('\u001e'),
  )
  return [cafe.busy, cafe.asking, cafe.idle, cafe.hiddenTables, ...tables].join('\u001d')
}

files.hooks/wire.ts:
// What the café sends to its web page, and how the page reads what it is sent.
//
// Two reporters write it. The hooks module sends its whole table now and then
// (a snap). scripts/report.mjs, which Claude Code runs for each hook event
// wherever the hooks module does not run (a task in the Claude app, say),
// sends each event as it happens, trimmed here to what the café shows: a
// tool's name, one short word for what it works on, an agent's type and its
// task's few words. Never a prompt, a file's content, a command's arguments or
// what a tool answered.
//
// The server reads both and trusts neither: every field is checked and cut
// to a length here.
//
// Pure: no `$` here and nothing of Node's, so a session, the reporter, the
// server and a test all run the same code.

import type { Act } from './describe'
import { actOfCall, clip, folderName, label, targetOf, tidy } from './describe'
import type { Snap } from './view'
import { parseSnap } from './view'

/** The app a session runs in, as well as its reporter can tell; `''` when it cannot. */
export type App = 'claude' | 'code' | 'cloud' | 'cli' | 'vscode' | 'sdk' | ''

const APPS: readonly App[] = ['claude', 'code', 'cloud', 'cli', 'vscode', 'sdk', '']

/** An agent the main loop left at work in the background, as its Stop event lists it. */
export type Bg = { id: string; type: string; task: string; isRunning: boolean }

/** What an Agent call asks for: the agent's type, its task's few words, and its name. */
export type Order = { type: string; task: string; name: string }

/**
 * One hook event as the café keeps it. `agent` is the subagent whose loop the
 * event comes from, `''` for the main loop.
 */
export type Ev =
  | { e: 'start'; source: string }
  | { e: 'prompt'; pid: string }
  /** `bg` is what Stop lists still at work; null when the event did not say. */
  | { e: 'stop'; pid: string; hasFailed: boolean; bg: Bg[] | null }
  /** `type` is the calling agent's type (`''` for the main loop). */
  | { e: 'pre'; agent: string; type: string; id: string; tool: string; act: Act; target: string; order: Order | null }
  | { e: 'post'; agent: string; id: string; child: string }
  | { e: 'batch'; agent: string; ids: string[] }
  | { e: 'ask'; agent: string; tool: string; target: string }
  | { e: 'denied'; agent: string; id: string }
  | { e: 'sub'; agent: string; type: string }
  | { e: 'subend'; agent: string; hasFailed: boolean }
  | { e: 'idle'; name: string }
  | { e: 'elicit'; agent: string }
  | { e: 'elicited'; agent: string }
  | { e: 'end'; reason: string }
  /** The main loop has answered and waits for the person (a turn that was interrupted has no Stop). */
  | { e: 'waiting' }

/** A whole table, from the hooks module. */
export type SnapPost = { v: 1; kind: 'snap'; app: App; link: string; snap: Snap }
/** A session is over: its table goes. */
export type ByePost = { v: 1; kind: 'bye'; id: string }
/** One hook event of one session, from scripts/report.mjs. */
export type EventPost = { v: 1; kind: 'event'; sid: string; app: App; title: string; link: string; ev: Ev }

export type Post = SnapPost | ByePost | EventPost

/** The most ids one batch carries, and the most background agents one stop lists. */
const MAX_IDS = 64
const MAX_BG = 32

type Fields = Readonly<Record<string, unknown>>

function isRecord(value: unknown): value is Fields {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function fieldsOf(value: unknown): Fields {
  return isRecord(value) ? value : {}
}

/** Text fit to show, cut to `max` widths. */
function word(value: unknown, max: number): string {
  return typeof value === 'string' ? clip(tidy(value), max) : ''
}

/**
 * An id as the engine makes them (a session's, an agent's, a tool call's, a
 * prompt's); `''` for anything else. Ids are never shown, only matched, and
 * this keeps out whatever is no id at all.
 */
export function idOf(value: unknown): string {
  return typeof value === 'string' && /^[A-Za-z0-9_.:-]{1,80}$/.test(value) ? value : ''
}

function oneOf<T extends string>(value: unknown, among: readonly T[], fallback: T): T {
  return among.find(item => item === value) ?? fallback
}

/** A link to a session on claude.ai, the one kind of link the page shows; `''` for anything else. */
export function sessionLink(value: unknown): string {
  return typeof value === 'string' && /^https:\/\/claude\.ai\/code\/session_[A-Za-z0-9]{8,64}$/.test(value) ? value : ''
}

function isAgentTool(tool: string): boolean {
  return tool === 'Agent' || tool === 'Task'
}

/** The words Stop uses for a background task that is over. */
const OVER: ReadonlySet<string> = new Set(['completed', 'failed', 'killed', 'stopped', 'cancelled', 'canceled', 'error'])

/** What Stop lists still at work; null when it lists nothing at all (an older Claude Code). */
function backgroundOf(value: unknown): Bg[] | null {
  if (!Array.isArray(value)) return null
  const out: Bg[] = []
  for (const item of value.slice(0, MAX_BG)) {
    const task = fieldsOf(item)
    const id = idOf(task['id'])
    // Stop lists background shells too: only agents take a seat.
    if (id === '' || (task['type'] !== undefined && task['type'] !== 'subagent')) continue
    out.push({
      id,
      type: label(String(task['agent_type'] ?? ''), 40),
      task: label(String(task['description'] ?? ''), 80),
      // Any word but one for an end: an agent Stop lists as still there is.
      isRunning: !OVER.has(String(task['status'] ?? '')),
    })
  }
  return out
}

/**
 * One hook event's input, as Claude Code hands it to a hook on stdin, trimmed
 * to what the café shows; undefined for an event the café has no use for.
 *
 * This runs in the session, before anything leaves it.
 */
export function eventOf(input: unknown): Ev | undefined {
  const fields = fieldsOf(input)
  const agent = idOf(fields['agent_id'])
  const tool = clip(tidy(String(fields['tool_name'] ?? '')), 80)
  const toolInput = fieldsOf(fields['tool_input'])
  switch (fields['hook_event_name']) {
    case 'SessionStart':
      return { e: 'start', source: word(fields['source'], 16) }
    case 'UserPromptSubmit':
      return { e: 'prompt', pid: idOf(fields['prompt_id']) }
    case 'Stop':
      return { e: 'stop', pid: idOf(fields['prompt_id']), hasFailed: false, bg: backgroundOf(fields['background_tasks']) }
    case 'StopFailure':
      // A subagent's turn that failed ends the subagent; the main loop's ends
      // its turn, and says nothing of the agents it left at work.
      if (agent !== '') return { e: 'subend', agent, hasFailed: true }
      return { e: 'stop', pid: idOf(fields['prompt_id']), hasFailed: true, bg: null }
    case 'PreToolUse': {
      const id = idOf(fields['tool_use_id'])
      if (id === '' || tool === '') return undefined
      const order = isAgentTool(tool)
        ? {
            type: label(String(toolInput['subagent_type'] ?? ''), 40),
            task: label(String(toolInput['description'] ?? ''), 80),
            name: label(String(toolInput['name'] ?? ''), 40),
          }
        : null
      const type = agent === '' ? '' : label(String(fields['agent_type'] ?? ''), 40)
      return { e: 'pre', agent, type, id, tool, act: actOfCall(tool, toolInput), target: targetOf(tool, toolInput), order }
    }
    case 'PostToolUse':
    case 'PostToolUseFailure': {
      const id = idOf(fields['tool_use_id'])
      if (id === '') return undefined
      // An Agent call answers with the id of the agent it started: only that is read of it.
      const child = isAgentTool(tool) ? idOf(fieldsOf(fields['tool_response'])['agentId']) : ''
      return { e: 'post', agent, id, child }
    }
    case 'PostToolBatch': {
      const calls = Array.isArray(fields['tool_calls']) ? fields['tool_calls'] : []
      const ids = calls
        .slice(0, MAX_IDS)
        .map(call => idOf(fieldsOf(call)['tool_use_id']))
        .filter(id => id !== '')
      return { e: 'batch', agent, ids }
    }
    case 'PermissionRequest':
      return { e: 'ask', agent, tool, target: targetOf(tool, toolInput) }
    case 'PermissionDenied': {
      const id = idOf(fields['tool_use_id'])
      return id === '' ? undefined : { e: 'denied', agent, id }
    }
    case 'SubagentStart':
      return agent === '' ? undefined : { e: 'sub', agent, type: label(String(fields['agent_type'] ?? ''), 40) }
    case 'SubagentStop':
      return agent === '' ? undefined : { e: 'subend', agent, hasFailed: false }
    case 'TeammateIdle': {
      const name = label(String(fields['teammate_name'] ?? ''), 40)
      return name === '' ? undefined : { e: 'idle', name }
    }
    case 'Elicitation':
      return { e: 'elicit', agent }
    case 'ElicitationResult':
      return { e: 'elicited', agent }
    case 'SessionEnd':
      return { e: 'end', reason: word(fields['reason'], 24) }
    case 'Notification':
      return fields['notification_type'] === 'idle_prompt' ? { e: 'waiting' } : undefined
    default:
      return undefined
  }
}

/** Where reports go, and the key that lets them in. */
export type Inbox = { url: string; key: string }

/**
 * The inbox of the café's web page at `base` (the page's address, as the
 * person set it up); undefined when either is missing or the address is not
 * one a report may go to: https, or http to this very machine.
 */
export function inboxOf(base: unknown, key: unknown): Inbox | undefined {
  if (typeof base !== 'string' || typeof key !== 'string') return undefined
  const address = base.trim()
  const secret = key.trim()
  if (address === '' || secret === '' || !URL.canParse(address)) return undefined
  const url = new URL(address)
  const isHere = url.hostname === 'localhost' || url.hostname === '127.0.0.1' || url.hostname === '[::1]'
  if (url.protocol !== 'https:' && !(url.protocol === 'http:' && isHere)) return undefined
  if (url.username !== '' || url.password !== '') return undefined
  url.search = ''
  url.hash = ''
  if (!url.pathname.endsWith('/')) url.pathname += '/'
  return { url: new URL('in', url).toString(), key: secret }
}

/**
 * True when the plugin's settings name the web page: `web_url` is filled in
 * (as hooks.json checks before it runs the reporter). web.json is then not
 * read, and the key must come from `web_key`.
 */
export function isWebSet(url: unknown): boolean {
  return typeof url === 'string' && url.trim() !== ''
}

/** The inbox web.json names, as `{ "url": "https://…", "key": "…" }`. */
export function inboxOfFile(config: unknown): Inbox | undefined {
  if (typeof config !== 'object' || config === null) return undefined
  const fields = config as Readonly<Record<string, unknown>>
  return inboxOf(fields['url'], fields['key'])
}

/** The app a hook runs in, from the environment Claude Code gives it. */
export function appOf(env: Readonly<Record<string, string | undefined>>): App {
  const entry = env['CLAUDE_CODE_ENTRYPOINT'] ?? ''
  if (entry === 'remote_cowork' || env['CLAUDE_CODE_SESSION_ORIGIN'] === 'claude_ai_chat') return 'claude'
  if (env['CLAUDE_CODE_REMOTE'] === 'true') return 'cloud'
  if (entry.includes('desktop')) return 'code'
  if (entry.includes('vscode')) return 'vscode'
  if (entry === 'cli') return 'cli'
  if (entry.startsWith('sdk')) return 'sdk'
  return ''
}

/** The claude.ai link to a session that runs in the cloud; `''` for one that does not. */
export function linkOf(env: Readonly<Record<string, string | undefined>>): string {
  const remote = env['CLAUDE_CODE_REMOTE_SESSION_ID'] ?? ''
  const found = /^cse_([A-Za-z0-9]{8,64})$/.exec(remote)
  return found === null ? '' : sessionLink(`https://claude.ai/code/session_${found[1]}`)
}

/**
 * A session's table name: its folder's name. Not its title, which is written
 * from the person's first prompt. A task in the Claude app runs in a
 * workspace whose folder says nothing of it: it has no name here.
 */
export function titleFor(app: App, cwd: unknown): string {
  if (app === 'claude') return ''
  return typeof cwd === 'string' ? folderName(cwd) : ''
}

/**
 * The report of one hook event: the event trimmed (eventOf), and which
 * session of which app it comes from. Undefined for an event the café has no
 * use for, or one that names no session.
 *
 * @param input the hook's input, as Claude Code hands it over on stdin
 * @param env the environment Claude Code runs the hook in
 */
export function eventPostOf(input: unknown, env: Readonly<Record<string, string | undefined>>): EventPost | undefined {
  const ev = eventOf(input)
  if (ev === undefined) return undefined
  const fields = fieldsOf(input)
  const sid = idOf(fields['session_id']) || idOf(env['CLAUDE_CODE_SESSION_ID'])
  if (sid === '') return undefined
  const app = appOf(env)
  return { v: 1, kind: 'event', sid, app, title: titleFor(app, fields['cwd']), link: linkOf(env), ev }
}

function parseBg(value: unknown): Bg[] {
  if (!Array.isArray(value)) return []
  const out: Bg[] = []
  for (const item of value.slice(0, MAX_BG)) {
    const fields = fieldsOf(item)
    const id = idOf(fields['id'])
    if (id === '') continue
    out.push({ id, type: word(fields['type'], 40), task: word(fields['task'], 80), isRunning: fields['isRunning'] === true })
  }
  return out
}

function parseOrder(value: unknown): Order | null {
  if (!isRecord(value)) return null
  return { type: word(value['type'], 40), task: word(value['task'], 80), name: word(value['name'], 40) }
}

const ACTS: readonly Act[] = [
  'read',
  'search',
  'write',
  'run',
  'web',
  'delegate',
  'plan',
  'ask',
  'tool',
  'think',
  'rest',
  'done',
  'fail',
]

/** Reads one event of a post; undefined for one of a shape the café does not know. */
export function parseEv(value: unknown): Ev | undefined {
  if (!isRecord(value)) return undefined
  const agent = idOf(value['agent'])
  switch (value['e']) {
    case 'start':
      return { e: 'start', source: word(value['source'], 16) }
    case 'prompt':
      return { e: 'prompt', pid: idOf(value['pid']) }
    case 'stop':
      return {
        e: 'stop',
        pid: idOf(value['pid']),
        hasFailed: value['hasFailed'] === true,
        bg: Array.isArray(value['bg']) ? parseBg(value['bg']) : null,
      }
    case 'pre': {
      const id = idOf(value['id'])
      const tool = word(value['tool'], 80)
      if (id === '' || tool === '') return undefined
      return {
        e: 'pre',
        agent,
        type: agent === '' ? '' : word(value['type'], 40),
        id,
        tool,
        act: oneOf(value['act'], ACTS, 'tool'),
        target: word(value['target'], 60),
        order: parseOrder(value['order']),
      }
    }
    case 'post': {
      const id = idOf(value['id'])
      return id === '' ? undefined : { e: 'post', agent, id, child: idOf(value['child']) }
    }
    case 'batch': {
      const ids = Array.isArray(value['ids']) ? value['ids'].slice(0, MAX_IDS).map(idOf).filter(id => id !== '') : []
      return { e: 'batch', agent, ids }
    }
    case 'ask':
      return { e: 'ask', agent, tool: word(value['tool'], 80), target: word(value['target'], 60) }
    case 'denied': {
      const id = idOf(value['id'])
      return id === '' ? undefined : { e: 'denied', agent, id }
    }
    case 'sub':
      return agent === '' ? undefined : { e: 'sub', agent, type: word(value['type'], 40) }
    case 'subend':
      return agent === '' ? undefined : { e: 'subend', agent, hasFailed: value['hasFailed'] === true }
    case 'idle': {
      const name = word(value['name'], 40)
      return name === '' ? undefined : { e: 'idle', name }
    }
    case 'elicit':
      return { e: 'elicit', agent }
    case 'elicited':
      return { e: 'elicited', agent }
    case 'end':
      return { e: 'end', reason: word(value['reason'], 24) }
    case 'waiting':
      return { e: 'waiting' }
    default:
      return undefined
  }
}

/**
 * Reads what a reporter posted. Anything of another shape is no post, and
 * every string is cut to a length, whatever the reporter sent.
 */
export function parsePost(value: unknown): Post | undefined {
  if (!isRecord(value) || value['v'] !== 1) return undefined
  switch (value['kind']) {
    case 'snap': {
      const snap = parseSnap(value['snap'])
      if (snap === undefined) return undefined
      return { v: 1, kind: 'snap', app: oneOf(value['app'], APPS, ''), link: sessionLink(value['link']), snap }
    }
    case 'bye': {
      const id = idOf(value['id'])
      return id === '' ? undefined : { v: 1, kind: 'bye', id }
    }
    case 'event': {
      const sid = idOf(value['sid'])
      const ev = parseEv(value['ev'])
      if (sid === '' || ev === undefined) return undefined
      return {
        v: 1,
        kind: 'event',
        sid,
        app: oneOf(value['app'], APPS, ''),
        title: word(value['title'], 40),
        link: sessionLink(value['link']),
        ev,
      }
    }
    default:
      return undefined
  }
}

