  gear: ['.#.#.#.', '#######', '.##a##.', '##aaa##', '.##a##.', '#######', '.#.#.#.'],
  people: ['.##....', '.##..aa', '####.aa', '####aaa', '####aaa', '....aaa', '.......'],
  book: ['.......', '###.###', '#aa#aa#', '#aa#aa#', '#aa#aa#', '###.###', '.......'],
  lens: ['.###...', '#aaa#..', '#aaa#..', '#aaa#..', '.###...', '....##.', '.....##'],
  list: ['a.####.', '.......', 'a.####.', '.......', 'a.###..', '.......', 'a.####.'],
  bang: ['..###..', '..###..', '..###..', '..###..', '.......', '..###..', '..###..'],
  query: ['.####..', '##..##.', '....##.', '...##..', '..##...', '.......', '..##...'],
  check: ['.......', '......#', '.....##', '#...##.', '##.##..', '.###...', '..#....'],
  cross: ['#.....#', '##...##', '.##.##.', '..###..', '.##.##.', '##...##', '#.....#'],
}

